#!/usr/bin/env node
// Golden-vector check for the TTN decoder (payload v1 + ICD v3 frames).
// Run from SW/Current/TTN:  node check_vectors.js
// Vectors are generated by Firmware/tools/gen_vectors.py — never edit the JSON.

const fs = require("fs");
const path = require("path");
const decoder = require("./decoder.js");

const VEC = path.join(__dirname, "..", "Firmware", "host_tests", "vectors");

let fails = 0;
function check(name, cond, detail) {
  if (cond) {
    console.log(`  ok    ${name}`);
  } else {
    fails++;
    console.log(`  FAIL  ${name}${detail ? " — " + detail : ""}`);
  }
}

// ---- payload v1 (28 B) ----
const pv1 = JSON.parse(fs.readFileSync(path.join(VEC, "payload_v1.json")));
console.log("payload_v1.json");
for (const v of pv1.vectors) {
  const bytes = v.hex.split(" ").map((h) => parseInt(h, 16));
  const out = decoder.decodeUplink({ fPort: 1, bytes }).data;
  const e = v.expected;
  check(`${v.name}: temp`, out.temperature === e.temp, out.temperature);
  check(`${v.name}: humidity`, out.relativeHumidity === e.hum);
  check(`${v.name}: pressure`, out.pressure_hPa === e.pres / 10);
  // Battery quantizes to 255 steps over 1800 mV (~7 mV); saturating
  // vectors are the v2-clamp divergence case.
  const batExp = v.saturating ? Math.min(4300, Math.max(2500, e.bat_mv)) : e.bat_mv;
  check(`${v.name}: battery_mV`, Math.abs(out.battery_mV - batExp) <= 8,
        `${out.battery_mV} != ${batExp}`);
  check(`${v.name}: lux`, out.light_lux === e.lux);
  check(`${v.name}: lat`, out.latitude === e.lat / 1e6 || (!out.gps_valid && e.lat === 0),
        `${out.latitude} != ${e.lat / 1e6}`);
  check(`${v.name}: lon`, out.longitude === e.lon / 1e6 || (!out.gps_valid && e.lon === 0));
  check(`${v.name}: alt`, out.altitude_m === e.alt, `${out.altitude_m} != ${e.alt}`);
  check(`${v.name}: sats`, out.satellites === e.sat);
  check(`${v.name}: time`, out.time === (e.time ? new Date(e.time * 1000).toISOString() : null));
  check(`${v.name}: gps_valid`, out.gps_valid === !(e.lat === 0 && e.lon === 0 && e.sat === 0));
}

// ---- diagnostics v3 (24 B) ----
const icd = JSON.parse(fs.readFileSync(path.join(VEC, "icd_v3.json")));
console.log("icd_v3.json — diag frames");
for (const f of icd.diag_frames) {
  const bytes = f.hex.split(" ").map((h) => parseInt(h, 16));
  const out = decoder.decodeUplink({ fPort: 2, bytes }).data;
  const e = f.expected;
  check(`${f.name}: schema`, out.schema === 3);
  check(`${f.name}: fw`, out.fw_version === e.fw.join("."), out.fw_version);
  check(`${f.name}: boot_count`, out.boot_count === e.bootCount);
  check(`${f.name}: gps_timeouts`, out.failures.gps_timeouts === e.gpsTimeouts);
  check(`${f.name}: sensor_read`, out.failures.sensor_read === e.sensorReadFailures);
  check(`${f.name}: gps_consecutive_fails`,
        out.gps_consecutive_fails === e.gpsConsecFails);
  check(`${f.name}: power_flags`,
        JSON.stringify(out.power_flags) ===
        JSON.stringify(e.powerFlags & 1 ? ["degraded"] : []));
  check(`${f.name}: last_ttff_s`, out.last_ttff_s === (e.lastTtff === 255 ? null : e.lastTtff));
  check(`${f.name}: link_margin_db`, out.link_margin_db === (e.linkMargin === 255 ? null : e.linkMargin));
  check(`${f.name}: gateways`, out.gateways === (e.gwCnt === 255 ? null : e.gwCnt));
  check(`${f.name}: ota_status`, out.ota_status === (e.otaStatus === 3 ? "download_failed" : e.otaStatus === 0 ? "none" : e.otaStatus === 1 ? "staged" : e.otaStatus));
  check(`${f.name}: flags`,
        JSON.stringify(out.flags) ===
        JSON.stringify([[1, "gps_valid"], [2, "ota_pending_verify"],
                        [4, "recovery_mode"]]
            .filter(([b]) => e.flags2 & b).map(([, n]) => n)));
}

console.log("icd_v3.json — downlink commands");
for (const c of icd.downlink_commands) {
  const bytes = c.hex.split(" ").map((h) => parseInt(h, 16));
  // decode side (decoder.js must define decodeDownlink — TTN's "Downlink
  // decoder" slot calls it for every queued command)
  const dec = decoder.decodeDownlink({ fPort: 3, bytes });
  check(`${c.name}: decode magic/opcode`,
        dec.data && dec.data.opcode === c.opcode && dec.data.arg === 0,
        JSON.stringify(dec.data));
  check(`${c.name}: decode names it`,
        dec.data && typeof dec.data.command === "string" &&
        dec.data.command !== "UNKNOWN", JSON.stringify(dec.data));
  // encode roundtrip (decoder.js encodeDownlink)
  const rebuilt = decoder.encodeDownlink(
      { fPort: 3, data: { command: dec.data.command } });
  check(`${c.name}: encode roundtrip`,
        rebuilt.bytes && rebuilt.bytes[0] === 0x4D &&
        rebuilt.bytes[1] === c.opcode && rebuilt.bytes[2] === 0);
}

console.log("icd_v3.json — downlink robustness");
check("bad magic", decoder.decodeDownlink({ fPort: 3, bytes: [0x00, 1, 0] })
      .errors !== undefined);
check("bad fport", decoder.decodeDownlink({ fPort: 1, bytes: [0x4D, 1, 0] })
      .errors !== undefined);
check("bad length", decoder.decodeDownlink({ fPort: 3, bytes: [0x4D, 1] })
      .errors !== undefined);
check("reserved opcode warns",
      (decoder.decodeDownlink({ fPort: 3, bytes: [0x4D, 0x7A, 0] })
       .warnings || []).length === 1);

// ---- negative: wrong sizes / unknown schema must not throw ----
console.log("robustness");
check("fport 1 wrong size", decoder.decodeUplink({ fPort: 1, bytes: [1, 2, 3] }).data.error !== undefined);
check("unknown diag schema", decoder.decodeUplink({ fPort: 2, bytes: new Array(24).fill(0) }).data.error !== undefined);
check("unhandled fport", decoder.decodeUplink({ fPort: 9, bytes: [] }).data.info !== undefined);

if (fails) {
  console.log(`\n${fails} CHECK(S) FAILED`);
  process.exit(1);
}
console.log("\nall vector checks passed");
